const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let p = 0;
const N = data[p++];
const K = data[p++];
const T = data[p++];

const plates = data.slice(p, p + N);
p += N;
const group = data.slice(p, p + N);

const R = 9 * K + 1;
const INF = 0x3fffffff;
let dp = new Int32Array((K + 1) * R);
let next = new Int32Array((K + 1) * R);
dp.fill(INF);
dp[0] = 0;

let prefixGroup = 0;

for (let i = 0; i < N; i++) {
  prefixGroup += group[i];
  next.fill(INF);

  const minQ = Math.max(0, K - (N - i));
  const maxQ = Math.min(i, K);
  const minNextQ = Math.max(0, K - (N - i - 1));
  const maxNextQ = Math.min(i + 1, K);
  const edgeCost = i === N - 1 ? 0 : 1;

  for (let q = minQ; q <= maxQ; q++) {
    const base = q * R;
    const maxReward = 9 * q;

    for (let reward = 0; reward <= maxReward; reward++) {
      const cost = dp[base + reward];
      if (cost > T) continue;

      if (q >= minNextQ && q <= maxNextQ) {
        const newCost = cost + (edgeCost ? Math.abs(q - prefixGroup) : 0);
        if (newCost <= T) {
          const idx = base + reward;
          if (newCost < next[idx]) next[idx] = newCost;
        }
      }

      const nq = q + 1;
      if (nq <= K && nq >= minNextQ && nq <= maxNextQ) {
        const newReward = reward + plates[i];
        const newCost = cost + (edgeCost ? Math.abs(nq - prefixGroup) : 0);
        if (newCost <= T) {
          const idx = nq * R + newReward;
          if (newCost < next[idx]) next[idx] = newCost;
        }
      }
    }
  }

  const temp = dp;
  dp = next;
  next = temp;
}

let answer = 0;
const base = K * R;
for (let reward = 0; reward < R; reward++) {
  if (dp[base + reward] <= T) answer = reward;
}

console.log(answer);
